                            'code' => $normalized,
                            'name' => $normalized,
                            'is_active' => true,
                        ]);
                    }
                    $model->setAttribute('payment_type_id', (int) $pt->getKey());
                } catch (\Throwable $e) {
                    // ignore; validation may catch later
