    /**
     * Accesor virtual 'status' para exponer una etiqueta estable (REGISTERED/CONFIRMED/APPLIED)
     * a partir del código del catálogo (REG/CONF/CONC).
     */
    public function getStatusAttribute(): ?string
    {
        // Resolver código desde la relación si está cargada; si no, consulta puntual por id
        $code = null;
        try {
            if ($this->relationLoaded('paymentStatus')) {
                /** @var null|\App\Models\PaymentStatus $rel */
                $rel = $this->getRelation('paymentStatus');
                $code = $rel?->getAttribute('code');
            } else {
                $psId = $this->getAttribute('payment_status_id');
                if ($psId) {
                    /** @var null|\App\Models\PaymentStatus $ps */
                    $ps = PaymentStatus::query()->find((int) $psId);
                    $code = $ps?->getAttribute('code');
                }
            }
        } catch (\Throwable $e) {
            // ignore
        }

        if (! is_string($code) || $code === '') {
            return null;
        }

        $map = [
            'REG' => 'REGISTERED',
            'CONF' => 'CONFIRMED',
            'CONC' => 'APPLIED',
            'VOID' => 'VOID',
        ];

        return $map[strtoupper($code)] ?? $code;
    }

    /**
     * Mutador virtual 'status' para permitir asignaciones con etiquetas de negocio
     * (REGISTERED/CONFIRMED/APPLIED) y reflejarlo en payment_status_id mediante el catálogo.
     *
     * @param  mixed  $value
     */
    public function setStatusAttribute($value): void
    {
        $val = is_string($value) ? strtoupper($value) : null;
        $uiToCode = [
            'REGISTERED' => 'REG',
            'CONFIRMED' => 'CONF',
            'APPLIED' => 'CONC',
            'VOID' => 'VOID',
            'VOIDED' => 'VOID',
        ];

        $code = $val ? ($uiToCode[$val] ?? $val) : null; // permite pasar directamente códigos REG/CONF/CONC
        $id = null;
        if ($code) {
            /** @var null|\App\Models\PaymentStatus $ps */
            $ps = PaymentStatus::query()->where('code', $code)->first();
            if ($ps) {
                $id = (int) $ps->getKey();
            }
        }

        $this->attributes['payment_status_id'] = $id;
    }

